import{_ as t,o as r,c as n,a2 as o}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"4-1 Antd pro 介绍","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/11.react(谢杰)/codestation后端/4-1 Antd pro 介绍.md","filePath":"DuOneClass/11.react(谢杰)/codestation后端/4-1 Antd pro 介绍.md"}'),a={name:"DuOneClass/11.react(谢杰)/codestation后端/4-1 Antd pro 介绍.md"};function m(p,e,l,s,i,d){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="_4-1-antd-pro-介绍" tabindex="-1">4-1 Antd pro 介绍 <a class="header-anchor" href="#_4-1-antd-pro-介绍" aria-label="Permalink to &quot;4-1 Antd pro 介绍&quot;">​</a></h1><p>前面介绍过 <em>Antd</em>，这是蚂蚁旗下的一个组件库，提供了 <em>React</em> 和 <em>Vue</em> 双版本，这就类似于 <em>Vue</em> 的 <em>ElementUI</em>。</p><p>而这里要介绍的 <em>Antd pro</em>，则是蚂蚁推出的集成了 <em>Antd</em> 组件库的<strong>后台集成解决方案</strong>，类似于之前我们所学的 <em>vue-element-admin</em></p><blockquote><p>补充一下：</p><p><em>vue-element-admin</em> 使用的是 <em>vue 2.x</em>，如果想要基于 <em>vue 3.x</em> 的后台管理集成方案，可以使用 <em>vue-element-plus-admin</em>，官网地址：<em><a href="https://kailong110120130.gitee.io/vue-element-plus-admin-doc/" target="_blank" rel="noreferrer">https://kailong110120130.gitee.io/vue-element-plus-admin-doc/</a></em></p><p>另外，蚂蚁同样也推出了基于 <em>vue</em> 技术栈的 <em>antd pro vue</em>，不过 <em>antd pro vue</em> 使用的 <em>vue 2.x</em>，官网地址：<em><a href="https://pro.antdv.com/" target="_blank" rel="noreferrer">https://pro.antdv.com/</a></em></p></blockquote><p><em>Antd pro</em> 的官网地址：<em><a href="https://pro.ant.design/zh-CN/" target="_blank" rel="noreferrer">https://pro.ant.design/zh-CN/</a></em></p><p>由于后期我们所使用的 <em>Umi Max</em> 集成了 <em>Antd pro</em> 在里面，所以我们需要提前了解 <em>Antd pro</em>，要了解的主要有以下几个点：</p><ul><li>新增布局</li><li>将文件加入菜单和路由</li><li><em>UI</em> 配置（<em>layout</em> 配置对象）</li></ul><blockquote><p><em><a href="https://pro.ant.design/zh-CN/docs/new-page" target="_blank" rel="noreferrer">https://pro.ant.design/zh-CN/docs/new-page</a></em></p></blockquote><p><em><strong>ProComponents</strong></em></p><p><em>ProComponents</em> 是基于 <em>Ant Design</em> 而开发的模板组件，提供了更高级别的抽象支持，开箱即用。可以显著的提升制作 <em>CRUD</em> 页面的效率，更加专注于页面。</p><p><em>ProComponents</em> 官网：<em><a href="https://procomponents.ant.design/" target="_blank" rel="noreferrer">https://procomponents.ant.design/</a></em></p><p><em>ProComponents</em> 针对中后台系统中常用的组件进行了二次封装，主要包含：</p><ul><li>布局 <ul><li><a href="https://procomponents.ant.design/components/layout" target="_blank" rel="noreferrer">ProLayout</a> 解决布局的问题，提供开箱即用的菜单和面包屑功能</li><li><a href="https://procomponents.ant.design/components/card" target="_blank" rel="noreferrer">ProCard</a> 提供卡片切分以及栅格布局能力</li></ul></li><li>数据录入 <ul><li><a href="https://procomponents.ant.design/components/form" target="_blank" rel="noreferrer">ProForm</a> 表单模板组件，预设常见布局和行为</li></ul></li><li>数据展示 <ul><li><a href="https://procomponents.ant.design/components/table" target="_blank" rel="noreferrer">ProTable</a> 表格模板组件，抽象网络请求和表格格式化</li><li><a href="https://procomponents.ant.design/components/descriptions" target="_blank" rel="noreferrer">ProDescriptions</a> 定义列表模板组件，ProTable 的配套组件</li></ul></li><li>通用 <ul><li><a href="https://procomponents.ant.design/components/skeleton" target="_blank" rel="noreferrer">ProSkeleton</a> 页面级别的骨架屏</li></ul></li></ul>',13)])])}const _=t(a,[["render",m]]);export{u as __pageData,_ as default};
